JSON.stringify({
 nav:[...document.querySelectorAll('header a, nav a')].map(function(a){
   return (a.textContent||'').trim().slice(0,26)+' -> '+a.getAttribute('href');}).slice(0,40),
 foot:[...document.querySelectorAll('footer a')].map(function(a){
   return (a.textContent||'').trim().slice(0,26)+' -> '+a.getAttribute('href');}).slice(0,30),
 htmlOverflow:getComputedStyle(document.documentElement).overflow,
 bodyOverflow:getComputedStyle(document.body).overflow,
 htmlH:document.documentElement.scrollHeight, bodyH:document.body.scrollHeight,
 winH:innerHeight,
 focusStyles:(function(){var a=document.querySelector('header a');if(!a)return '?';
   a.focus();var s=getComputedStyle(a);return 'outline:'+s.outlineStyle+' '+s.outlineWidth+' / '+s.outlineColor;})(),
 autoplay:[...document.querySelectorAll('.swiper,.elementor-slides,[data-autoplay],video')].length,
 forms:[...document.querySelectorAll('form')].map(function(f){
   return [...f.querySelectorAll('input,select,textarea')].filter(function(i){return i.type!=='hidden';})
     .map(function(i){return (i.name||i.type)+(i.required?'*':'');}).join(' | ');})
})
